export function createStock(initial = {}) {
  const available = new Map(Object.entries(initial));
  return {
    available: (sku) => available.get(sku) ?? 0,
    reserve(sku, qty) {
      if (!Number.isInteger(qty) || qty <= 0)
        throw new RangeError('qty must be a positive integer');
      const have = available.get(sku) ?? 0;
      if (qty > have) throw new RangeError('insufficient stock for ' + sku);
      available.set(sku, have - qty);
    },
    release(sku, qty) {
      available.set(sku, (available.get(sku) ?? 0) + qty);
    },
  };
}

// A discount is { type: 'percent', value } or { type: 'fixed', cents }.
export function discountCents(subtotalCents, discounts = []) {
  let total = 0;
  for (const discount of discounts) {
    if (discount.type === 'percent')
      total += Math.round((subtotalCents * discount.value) / 100);
    else if (discount.type === 'fixed') total += discount.cents;
    else throw new TypeError('unknown discount type: ' + discount.type);
  }
  return Math.min(total, subtotalCents);
}

export function applyDiscounts(subtotalCents, discounts = []) {
  return subtotalCents - discountCents(subtotalCents, discounts);
}

// Converts between decimal amounts and integer cents.
export function toCents(amount) {
  if (typeof amount !== 'number' || !Number.isFinite(amount))
    throw new TypeError('amount must be a finite number');
  return Math.round(amount * 100);
}

export function fromCents(cents) {
  return cents / 100;
}

export function formatMoney(cents) {
  const sign = cents < 0 ? '-' : '';
  const abs = Math.abs(cents);
  return sign + '$' + Math.floor(abs / 100) + '.' + String(abs % 100).padStart(2, '0');
}

// Tax on an amount in cents, for a rate such as 0.0825.
export function taxCents(amountCents, rate) {
  if (typeof rate !== 'number' || rate < 0)
    throw new RangeError('rate must be a non-negative number');
  return Math.round(amountCents * rate);
}
